function validate(input) {
  const [{ Employee = [], Bonus = [] }] = input;
  const staff = new Set(), paid = new Set();
  for (const [id] of Employee) {
    if (id === null) return 'Every employee needs an empId.';
    if (staff.has(id)) return `empId ${id} appears twice in Employee.`;
    staff.add(id);
  }
  for (const [id, bonus] of Bonus) {
    if (id === null || !staff.has(id)) return `Bonus empId ${id} is not an employee.`;
    if (paid.has(id)) return `empId ${id} appears twice in Bonus.`;
    if (bonus === null) return 'Every bonus row needs an amount.';
    paid.add(id);
  }
  return null;
}

