function generate(rand, size) {
  const names = ['Brad', 'John', 'Dan', 'Thomas', 'Ana', 'Lee', 'Kim', 'Ravi'];
  const amounts = [0, 500, 999, 1000, 1001, 2000];
  const count = size === 'small' ? Math.floor(rand() * 8) : 1800;
  const Employee = [], Bonus = [];
  for (let id = 1; id <= count; id++) {
    const supervisor = id === 1 || rand() < 0.2 ? null : 1 + Math.floor(rand() * (id - 1));
    Employee.push([id, names[Math.floor(rand() * names.length)], supervisor, 1000 * (1 + Math.floor(rand() * 5))]);
    if (rand() < 0.6) {
      const bonus = size === 'small' ? amounts[Math.floor(rand() * amounts.length)] : Math.floor(rand() * 2001);
      Bonus.push([id, bonus]);
    }
  }
  return [{ Employee, Bonus }];
}
